// A generic C++11 function whose return type depends on its parameter.
// The trailing return type is necessary because the expression inside decltype
// uses the 'container' parameter, which is only in scope after the parameter list.
template <class C>
auto cbegin(const C& container) -> decltype(std::begin(container))
{
  // By passing a const container to std::begin, we get back a const_iterator.
  // The decltype expression correctly deduces this specific iterator type.
  return std::begin(container);
}

// Example: For a std::vector<int>, the return type becomes
// std::vector<int>::const_iterator.
// For an int[10], the return type becomes const int*.
